// 闪屏广告class ActiveAdvertModel {  final String? twinkleDate;  final List<PicUrls>? picUrls;  ActiveAdvertModel({this.picUrls, this.twinkleDate,});  factory ActiveAdvertModel.fromJson(Map<dynamic, dynamic> json) {    return ActiveAdvertModel(      picUrls : (json['picUrls'] as List).map((i) => PicUrls.fromJson(i)).toList(),      twinkleDate : json['twinkleDate'].toString(),    );  }}class PicUrls {  final String? picUrlAll;  final String? interlinkage;  final String? sortCode;  final String? synopsis;  PicUrls({this.picUrlAll, this.interlinkage, this.sortCode, this.synopsis});  factory PicUrls.fromJson(Map<dynamic, dynamic> json) {    return PicUrls(      picUrlAll : json['picUrlAll'].toString(),      interlinkage : json['interlinkage'].toString(),      sortCode : json['sortCode'].toString(),      synopsis : json['synopsis'].toString(),    );  }}// 弹窗广告class PopupAdvertModel {  final String? beginTime;    // 	展示开始时间  final String? endTime;      // 		展示结束时间  final String? interlinkage; // 	图片链接  final String? isShow;       //	是否显示 0：否 1：是  final String? isPlay;       // 是否限制时间播放 0：否 1：是  final String? picFullPath;  // 	弹窗广告图片地址  PopupAdvertModel({this.beginTime, this.endTime, this.interlinkage, this.isShow, this.isPlay, this.picFullPath});  factory PopupAdvertModel.fromJson(Map<dynamic, dynamic> json) {    return PopupAdvertModel(      beginTime : json['beginTime'].toString(),      endTime : json['endTime'].toString(),      interlinkage : json['interlinkage'].toString(),      isShow : json['isShow'].toString(),      isPlay : json['isPlay'].toString(),      picFullPath : json['picFullPath'].toString(),    );  }}